// @ 0x8244A670
void xactWave_Finalize(void* wave) {
    auto* self = static_cast<XactWaveRuntime*>(wave);
    self->flags |= 0x10;
    auto* instance = static_cast<XactWaveInstance*>(self->instance);
    if (instance != nullptr) {
        instance->Release();
        self->instance = nullptr;
    }
}
